  'my.title': 'સેટિંગ અને સેવ કરેલો ડેટા', 'my.intro': 'Nivesh Sahayak ના દરેક ડોક્યુમેન્ટ ટૂલને એક જ જગ્યાએથી સેટ કરો: તમારા બિઝનેસ, ગ્રાહક અને સપ્લાયર, આઇટમ અને સર્વિસ, નંબરિંગ અને ડિફૉલ્ટ. બધું આ જ બ્રાઉઝરમાં રહે છે. અમને કંઈ મોકલાતું નથી.',
