  'my.empty': 'અહીં હજી કંઈ સેવ નથી. ટૂલ વાપરશો તેમ આ ભરાતું જશે.', 'my.vault': 'આ બ્રાઉઝરમાં Nivesh Sahayakનાં બધાં ટૂલ આ જ ડેટા વાપરે છે.', 'my.local': 'આ જ બ્રાઉઝરમાં રાખેલું છે.',
