  'my.wipe.b': 'આ ડિવાઇસ પરથી બધું ડિલીટ કરો', 'my.wipe.c1': 'આ ડિવાઇસ પરથી બધા જ બિઝનેસ, ગ્રાહક, આઇટમ અને ડોક્યુમેન્ટ ડિલીટ કરવા છે? જરૂર હોય તો પહેલાં બેકઅપ ફાઇલ સેવ કરી લો.',
  'my.wipe.c2': 'પાકું કરવા માટે DELETE લખો.', 'my.wiped': 'આ ડિવાઇસ પરથી બધું ડિલીટ થઈ ગયું.', 'my.c.del': '"{name}" ડિલીટ કરવું છે? બેકઅપ ફાઇલ વગર આ પાછું નહીં આવે.', 'my.saved': 'સેવ થઈ ગયું.',
