  "app.makedc": "ડિલિવરી ચલણ",
  "app.made": "બન્યું: {x}",
  "app.local": "ડેટા હોમ ખૂલ્યું નહીં, તેથી ફક્ત આ જ સાઇટ પર આ બ્રાઉઝરમાં સેવ છે. આવતી વખતે તે ડેટા હોમમાં જશે.",
  "app.vault": "આ બ્રાઉઝરના ડેટા હોમમાં સેવ છે, જે Nivesh Sahayak ના દરેક ટૂલમાં શેર છે. અમને કંઈ મોકલાતું નથી.",
  "app.help": "આ કેવી રીતે કામ કરે છે",
  "app.helpp": "billing., cash-memo. અને credit-note. પર બનેલાં બિલ અહીં આપોઆપ દેખાય છે. મળેલા અને આપેલા પૈસા અહીં લખો; ઍપ તેને બિલો સાથે જોડે છે, એડવાન્સ રાખે છે અને બાકી અને હાથની કેશ કાઢે છે.",
  "app.invfix": "અહીં ચૂકતે થયેલાં ઇન્વૉઇસ બિલિંગ સાઇટ પર પણ પેઇડ દેખાશે.",
