  'td.trans': 'જે ટ્રાન્સપોર્ટર પાસે 10 કે ઓછી માલવાહક ગાડીઓ છે અને જે PAN સાથે ઘોષણાપત્ર આપે છે, તેને TDS વગર ચૂકવણી કરી શકાય છે.',
  'td.q': 'તમારું ગયા વર્ષનું ટર્નઓવર ₹10 કરોડથી વધુ હોય તો જ કાપો, અને આ વેચનાર પાસેથી વર્ષની ખરીદીના ₹50 લાખથી ઉપરના ભાગ પર જ.',
  'td.ib': 'ટેક્સ ઑડિટ ન હોય તેવા વ્યક્તિએ ચૂકવેલા ભાડા પર TDS એક જ વાર કપાય છે, વર્ષના કે ભાડાકરારના છેલ્લા મહિનાના ભાડામાંથી.',
