  "b1.c_tcs10g": "GST વગર કોઈ આઇટમ ₹10 લાખથી વધુ નથી, ફક્ત GST ઉમેરીને વધુ છે. એક્ટમાં \"વેલ્યુ\" લખ્યું છે અને આ લિમિટમાં GST ગણાય કે નહીં તે કોઈ સર્ક્યુલરે નક્કી કર્યું નથી. શું આ બિલ પર TCS લેવો છે?",
