  "b1.cntcs": "બિલ {no} પર {v} TCS લાગ્યો હતો. આ ક્રેડિટ નોટ તે TCS ઘટાડતી નથી: CBDT સર્ક્યુલર 17/2020 (પેરા 4.6.1) મુજબ સેલ્સ રિટર્ન પર કોઈ એડજસ્ટમેન્ટ નથી. ખરીદનાર આ TCS પોતાના ઇન્કમ ટેક્સ રિટર્નમાં ક્લેમ કરે છે.",
