  "b2.dep": "ઘસારો",
  "b2.closewdv": "ક્લોઝિંગ WDV",
  "b2.gain": "નફો {a}: એકાઉન્ટન્ટને પૂછો",
  "b2.farules": "ઘસારો કેવી રીતે ગણાય છે",
  "b2.farule1": "ખાતાનો ઘસારો કંપનીઝ એક્ટ, 2013 ના શેડ્યૂલ II મુજબ છે: દરેક પ્રકારની એસેટનું ઉપયોગી આયુષ્ય છે (જેમ કે કમ્પ્યુટર 3 વર્ષ, ફર્નિચર 10 વર્ષ, પ્લાન્ટ અને મશીનરી 15 વર્ષ, કાર 8 વર્ષ), બાકી વેલ્યુ સામાન્ય રીતે કિંમતના 5% થી વધુ હોતી નથી, અને વર્ષની વચ્ચે ઉમેરેલી કે વેચેલી એસેટ પર ફક્ત વપરાશના દિવસોનો ઘસારો લાગે છે. સ્ટ્રેટ લાઇન (SLM: દર વર્ષે સરખી રકમ) કે રિટન ડાઉન વેલ્યુ (WDV: બાકી રકમ પર નક્કી રેટ) પસંદ કરો. પ્રોપ્રાઇટર અને ફર્મ મોટે ભાગે આ જ રીત વાપરે છે; નિર્ણય તમારા એકાઉન્ટન્ટ લે છે.",
  "b2.farule2": "ઇન્કમ ટેક્સ ઘસારો દરેક બ્લોકનો અલગ ગણાય છે: બ્લોક રેટ પર રિટન ડાઉન વેલ્યુ (જેમ કે પ્લાન્ટ અને મશીનરી 15%, ફર્નિચર 10%, કમ્પ્યુટર 40%), વર્ષમાં 180 દિવસથી ઓછી વપરાયેલી એસેટ પર અડધો રેટ, અને વેચાણના પૈસા બ્લોકમાંથી ઘટે છે. આ ફક્ત ઇન્કમ ટેક્સ રિટર્ન માટે છે, ખાતામાં ક્યારેય નખાતું નથી. ભરેલા રેટ સામાન્ય બ્લોક રેટ છે: તમારા એકાઉન્ટન્ટ પાસે ખાતરી કરો, ખાસ કરીને 1 એપ્રિલ 2026 થી ઇન્કમ-ટેક્સ એક્ટ, 2025 હેઠળના વર્ષો માટે.",
  "b2.farule3": "તમે 'ઘસારો નાખો' દબાવો ત્યારે જ ઘસારો તમારા ખાતામાં જાય છે: વર્ષના છેલ્લા દિવસની (કે વર્ષની વચ્ચે આજની) જર્નલ એન્ટ્રી ઘસારાને ડેબિટ કરે છે અને દરેક એસેટ ઘટાડે છે. પછી એસેટ બદલો તો ફરી નાખો, ફક્ત તફાવત ઉમેરાશે.",
  "b2.k_bldg_off": "મકાન: ઓફિસ કે દુકાન",
